class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price

    def discounted(self, percent):
        return self.price * (1 - percent / 100)

tea = Product("Чай", 320)
coffee = Product("Кофе", 900)
print(tea.name, tea.discounted(10))      # Чай 288.0
print(coffee.name, coffee.discounted(10))  # Кофе 810.0

class Circle:
    PI = 3.14159

    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return Circle.PI * self.radius ** 2

print(Circle(2).area())   # 12.56636
print(Circle(1).area())   # 3.14159

