class Cart:
    def __init__(self):
        self.items = []

    def add_item(self, name, price):
        self.items.append((name, price))

    def total(self):
        return sum(price for _, price in self.items)


cart = Cart()
cart.add_item("Яблоко", 120)
cart.add_item("Хлеб", 45)
print(cart.total())
empty_cart = Cart()
print(empty_cart.total())
cart.add_item("Молоко", 80)
print(cart.total())
